/**
 * Run one iteration of the feature reviewer for all in_handoff features in
 * a single workspace. Intended to be called from the orchestrator poll loop
 * every FEATURE_REVIEW_INTERVAL cycles.
 */
export async function runFeatureReviewCycle(opts: RunFeatureReviewCycleOpts): Promise<void> {
  const {
    workspaceRoot,
    baseBranch,
    mgmtRepoOwner,
    mgmtRepoName,
    githubToken,
    anthropicApiKey,
    slackWebhookUrl,
    emit,
  } = opts;

  const CONFIDENCE_THRESHOLD = opts.semanticConfidenceThreshold ?? 0.80;

  if (!githubToken) {
    emit({ type: "feature_review_skipped", reason: "no_github_token" });
    return;
  }

  const featureIds = listFeatureIds(workspaceRoot);

  for (const featureId of featureIds) {
    const statusYaml = readStatusYaml(workspaceRoot, featureId);

    if (statusYaml.feature_status !== "in_handoff") continue;

    if (statusYaml.drift_detected) {
      emit({
        type: "feature_review_skipped",
        feature_id: featureId,
        reason: "drift_already_detected",
      });
      continue;
    }

    const featureBranchBaseSha = statusYaml.feature_branch_base_sha;
    if (!featureBranchBaseSha) {
      emit({
        type: "feature_review_skipped",
        feature_id: featureId,
        reason: "no_feature_branch_base_sha",
      });
      continue;
    }

    // ── Step 1: Compare feature_branch_base_sha..baseBranch ──────────────────
    let compareResult: GitHubCompareResult;
    try {
      compareResult = curlJson([
        "-s",
        "-H", `Authorization: token ${githubToken}`,
        "-H", "Accept: application/vnd.github+json",
        `https://api.github.com/repos/${mgmtRepoOwner}/${mgmtRepoName}/compare/${featureBranchBaseSha}...${baseBranch}`,
      ]) as GitHubCompareResult;
    } catch (e) {
      emit({
        type: "feature_review_compare_failed",
        feature_id: featureId,
        details: String(e),
      });
      continue;
    }

    if (compareResult.ahead_by === 0) {
      emit({ type: "feature_review_no_drift", feature_id: featureId });
      continue;
    }

    emit({
      type: "feature_review_new_commits",
      feature_id: featureId,
      new_commits: compareResult.ahead_by,
    });

    // ── Step 2: Extract files changed in new base commits ─────────────────────
    const newBaseFiles = (compareResult.files ?? []).map((f) => f.filename);

    // ── Step 3: Get files changed by this feature's management repo PR ────────
    const featureFiles: string[] = [];
    const handoffPrUrl = statusYaml.handoff_pr_url;
    if (handoffPrUrl) {
      const prMatch = /\/pull\/(\d+)$/.exec(handoffPrUrl);
      if (prMatch) {
        const prNumber = prMatch[1];
        try {
          const files = curlJson([
            "-s",
            "-H", `Authorization: token ${githubToken}`,
            "-H", "Accept: application/vnd.github+json",
            `https://api.github.com/repos/${mgmtRepoOwner}/${mgmtRepoName}/pulls/${prNumber}/files`,
          ]) as Array<{ filename: string }>;
          if (Array.isArray(files)) {
            featureFiles.push(...files.map((f) => f.filename));
          }
        } catch (e) {
          emit({
            type: "feature_review_pr_files_failed",
            feature_id: featureId,
            details: String(e),
          });
        }
      }
    }

    // ── Step 4: File-overlap classification ───────────────────────────────────
    const { hasOverlap, overlappingFiles } = classifyFileOverlap(newBaseFiles, featureFiles);

    if (!hasOverlap) {
      // Task-level: auto-rebase
      emit({
        type: "feature_review_task_level_drift",
        feature_id: featureId,
        new_commits: compareResult.ahead_by,
      });
      const rebaseResult = tryAutoRebase(opts, featureId);
      if (rebaseResult.success) {
        emit({ type: "feature_review_rebased", feature_id: featureId });
      } else {
        emit({
          type: "feature_review_rebase_conflict",
          feature_id: featureId,
          details: rebaseResult.conflictDetails,
        });
        const driftReason = [
          `Rebase conflict: ${compareResult.ahead_by} new commits on ${baseBranch}.`,
          rebaseResult.conflictDetails?.slice(0, 200),
        ]
          .filter(Boolean)
          .join(" ");
        await escalateFeatureDrift(opts, featureId, driftReason);
      }
      continue;
    }

    // File overlap — attempt semantic analysis
    emit({
      type: "feature_review_file_overlap",
      feature_id: featureId,
      overlapping_files: overlappingFiles,
    });

    if (anthropicApiKey) {
      try {
        const newBaseSummary = (compareResult.files ?? [])
          .map((f) => `${f.filename} (${f.status})`)
          .join("\n");
        const featureSummary = featureFiles.join("\n");

        const analysis = await runSemanticAnalysis(
          overlappingFiles,
          newBaseSummary,
          featureSummary,
          anthropicApiKey,
        );

        emit({
          type: "feature_review_semantic_analysis",
          feature_id: featureId,
          confidence: analysis.confidence,
          has_conflict: analysis.hasConflict,
          reasoning: analysis.reasoning,
        });

        if (analysis.confidence >= CONFIDENCE_THRESHOLD && !analysis.hasConflict) {
          // High confidence no conflict → treat as task-level
          emit({
            type: "feature_review_task_level_drift",
            feature_id: featureId,
            new_commits: compareResult.ahead_by,
            reason: "semantic_override",
          });
          const rebaseResult = tryAutoRebase(opts, featureId);
          if (rebaseResult.success) {
            emit({ type: "feature_review_rebased", feature_id: featureId });
          } else {
            const driftReason = `Semantic analysis passed (confidence=${analysis.confidence.toFixed(2)}) but rebase failed: ${rebaseResult.conflictDetails?.slice(0, 200) ?? "unknown"}`;
            await escalateFeatureDrift(opts, featureId, driftReason);
          }
        } else {
          const driftReason = `Semantic conflict (confidence=${analysis.confidence.toFixed(2)}): ${analysis.reasoning}. Overlapping files: ${overlappingFiles.slice(0, 3).join(", ")}`;
          await escalateFeatureDrift(opts, featureId, driftReason);
        }
      } catch (e) {
        emit({
          type: "feature_review_semantic_failed",
          feature_id: featureId,
          details: String(e),
        });
        // Semantic analysis failed — escalate conservatively
        const driftReason = `File overlap on ${overlappingFiles.slice(0, 3).join(", ")} with ${compareResult.ahead_by} new base commits (semantic analysis unavailable)`;
        await escalateFeatureDrift(opts, featureId, driftReason);
      }
    } else {
      // No Anthropic key — escalate directly
      const driftReason = `File overlap on ${overlappingFiles.slice(0, 3).join(", ")} with ${compareResult.ahead_by} new base commits`;
      await escalateFeatureDrift(opts, featureId, driftReason);
    }
  }
}

/**
 * Feature Reviewer Daemon (T4).
 *
 * Poll step that runs every FEATURE_REVIEW_INTERVAL cycles. For each
 * in_handoff feature it detects drift (new commits on the base branch since
 * the feature started) and routes to one of three outcomes:
 *
 *   1. No new commits → skip.
 *   2. New commits, no file overlap → auto-rebase feature branch onto base;
 *      on rebase conflict fall through to escalation.
 *   3. New commits, file overlap → optional Claude API semantic analysis
 *      (confidence ≥ threshold → treat as no-overlap/auto-rebase;
 *       confidence < threshold → feature-level escalation).
 *
 * Feature-level escalation:
 *   - Sets drift_detected: true + drift_reason in status.yaml on the feature branch.
 *   - POSTs to SLACK_WEBHOOK_URL if set; skips gracefully if absent.
 */

import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { execSync, spawnSync } from "node:child_process";
import { join } from "node:path";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import { buildGitEnv } from "../git-env.js";
import { curlJson } from "../utils/curl-json.js";
import {
  featuresRoot,
  featureBranchName,
  statusYamlAbsPath,
  statusYamlRelPath,
} from "../paths.js";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface RunFeatureReviewCycleOpts {
  workspaceRoot: string;
  baseBranch: string;
  mgmtRepoOwner: string;
  mgmtRepoName: string;
  githubToken: string;
  reviewerGithubToken?: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  anthropicApiKey?: string;
  slackWebhookUrl?: string;
  /** Confidence threshold for semantic analysis. Default: 0.80. */
  semanticConfidenceThreshold?: number;
  emit: (event: Record<string, unknown>) => void;
}

interface StatusYaml {
  feature_status?: string;
  feature_branch?: string;
  feature_branch_base_sha?: string | null;
  handoff_pr_url?: string | null;
  impl_feature_prs?: ImplFeaturePr[];
  drift_detected?: boolean;
  drift_reason?: string | null;
  [key: string]: unknown;
}

interface ImplFeaturePr {
  repo: string;
  url: string;
  status: "open" | "merged";
}

interface GitHubCompareResult {
  ahead_by: number;
  files?: GitHubFile[];
  [key: string]: unknown;
}

interface GitHubFile {
  filename: string;
  status: string;
  patch?: string;
  [key: string]: unknown;
}

export interface SemanticAnalysisResult {
  confidence: number;
  hasConflict: boolean;
  reasoning: string;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function listFeatureIds(workspaceRoot: string): string[] {
  const docsPath = featuresRoot(workspaceRoot);
  if (!existsSync(docsPath)) return [];
  try {
    return readdirSync(docsPath, { withFileTypes: true })
      .filter((e) => e.isDirectory())
      .map((e) => e.name);
  } catch {
    return [];
  }
}

function readStatusYaml(workspaceRoot: string, featureId: string): StatusYaml {
  const statusPath = statusYamlAbsPath(workspaceRoot, featureId);
  if (!existsSync(statusPath)) return {};
  try {
    return parseYaml(readFileSync(statusPath, "utf-8")) as StatusYaml;
  } catch {
    return {};
  }
}

/**
 * Classify whether new base commits overlap with files changed by the feature.
 * Exported for unit testing.
 */
export function classifyFileOverlap(
  newBaseFiles: string[],
  featureFiles: string[],
): { hasOverlap: boolean; overlappingFiles: string[] } {
  const featureFileSet = new Set(featureFiles);
  const overlappingFiles = newBaseFiles.filter((f) => featureFileSet.has(f));
  return { hasOverlap: overlappingFiles.length > 0, overlappingFiles };
}

/**
 * Call Claude API to semantically classify whether overlapping file changes
 * are likely to conflict. Returns a confidence score and conflict verdict.
 * Exported for unit testing with a mocked fetch.
 */
export async function runSemanticAnalysis(
  overlappingFiles: string[],
  newBaseFileSummary: string,
  featureFileSummary: string,
  anthropicApiKey: string,
): Promise<SemanticAnalysisResult> {
  const prompt = [
    "You are analyzing whether code changes from two separate sources conflict.",
    "",
    `Files changed in both new base commits and the in-progress feature: ${overlappingFiles.join(", ")}`,
    "",
    "New base commit changes (summary):",
    newBaseFileSummary.slice(0, 2000),
    "",
    "In-progress feature changes (summary):",
    featureFileSummary.slice(0, 2000),
    "",
    "Do these changes conflict semantically? Respond ONLY with valid JSON:",
    '{"confidence": <0.0-1.0, where 1.0 = certain no conflict>, "has_conflict": <boolean>, "reasoning": "<one sentence>"}',
  ].join("\n");

  const response = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: {
      "x-api-key": anthropicApiKey,
      "anthropic-version": "2023-06-01",
      "content-type": "application/json",
    },
    body: JSON.stringify({
      model: "claude-haiku-4-5-20251001",
      max_tokens: 256,
      messages: [{ role: "user", content: prompt }],
    }),
  });

  if (!response.ok) {
    throw new Error(`Anthropic API error ${response.status}: ${await response.text()}`);
  }

  const data = (await response.json()) as {
    content: Array<{ type: string; text: string }>;
  };
  const text = data.content.find((c) => c.type === "text")?.text ?? "";

  const jsonMatch = /\{[\s\S]*?\}/.exec(text);
  if (!jsonMatch) {
    throw new Error(`Cannot parse semantic analysis JSON from: ${text}`);
  }

  const parsed = JSON.parse(jsonMatch[0]) as {
    confidence: number;
    has_conflict: boolean;
    reasoning: string;
  };

  return {
    confidence: parsed.confidence,
    hasConflict: parsed.has_conflict,
    reasoning: parsed.reasoning,
  };
}

